steps.script:
var MT = load("res://scripts/rules/movetypes/MoveType.gd")
var s = GameState.state
var cap: Dictionary = s.units.U_SHIELD_CAPTAIN_A.models[0].duplicate(true)
var wzm: Dictionary = s.units.U_WAZBOM_BLASTAJET.models[0]
return MT.sweep_moves_through(MT.contact_tolerant_mover(cap), Vector2(1356.0, 420.0), Vector2(1592.0, 420.0), wzm, Vector2(1420.0, 300.0))

var sm: Array = PhaseManager.get_current_phase_instance().active_moves["U_SHIELD_CAPTAIN_A"]["staged_moves"]
if sm.is_empty():
	return -1.0
var d = sm[0].get("dest", Vector2.ZERO)
var p: Vector2 = d if d is Vector2 else Vector2(float(d[0]), float(d[1]))
print("[ea08 aircraft] staged dest ", p)
return p.x > 1580.0 and absf(p.y - 420.0) < 6.0
